        val = tok[1:]
        datatype = None
        lang = None
        dt = re.search(r'\^\^<([^>]+)>$', val)
        if dt:
            datatype = dt.group(1)
            val = val[:dt.start()]
        else:
            lm = re.search(r'@[a-zA-Z-]+$', val)
            if lm:
                lang = lm.group(0)[1:]
                val = val[:lm.start()]
