    tokens = re.findall(pat, content)
    i = 0
    while i < len(tokens):
        n2 = parse_node(tokens, i)
        if n2 is None: i += 1; continue
        i = n2['end']; subj = n2['uri']
        while i < len(tokens):
            if tokens[i] == '.': i += 1; break
            if tokens[i] == ',': i += 1; continue
            pr = parse_node(tokens, i)
            if pr is None: i += 1; continue
            i = pr['end']; pred = pr['uri']
            if i >= len(tokens): break
            if tokens[i] == '.': i += 1; break
            while True:
                or2 = parse_node(tokens, i)
                if or2 is None: break
                i = or2['end']
                if 'val' in or2:
                    triples.append((subj, pred, or2['val'], or2.get('datatype'), or2.get('lang')))
                elif 'uri' in or2:
                    triples.append((subj, pred, or2['uri'], None, None))
                if i < len(tokens) and tokens[i] == ',': i += 1; continue
                break
    return triples, prefixes

def parse_node(tokens, i):
    if i >= len(tokens): return None
    tok = tokens[i]
    if tok.startswith('<') and tok.endswith('>'):
        return {'uri': tok[1:-1], 'end': i + 1}
    if ':' in tok and not tok.startswith('"') and not tok.startswith('['):
        parts = tok.split(':', 1)
        if len(parts) == 2 and parts[0] and parts[1]:
            return {'uri': tok, 'end': i + 1}
    if tok.startswith('"'):
        val = tok[1:]; datatype = None; lang = None
        dt = re.search(r'\^\^<([^>]+)>$', val)
        if dt: datatype = dt.group(1); val = val[:dt.start()]
        else:
            lm = re.search(r'@[a-zA-Z-]+$', val)
            if lm: lang = lm.group(0)[1:]; val = val[:lm.start()]
        return {'val': val, 'datatype': datatype, 'lang': lang, 'end': i + 1}
    if tok.startswith('['): return {'uri': '_:bnode', 'end': i + 1}
    return None

