def expand_uri(uri, prefixes):
    if uri.startswith('<') and uri.endswith('>'): return uri[1:-1]
    if ':' in uri:
        parts = uri.split(':', 1)
        if parts[0] in prefixes: return prefixes[parts[0]] + parts[1]
    return uri

