#!/usr/bin/env python3
"""Direct query execution against parsed Turtle data."""
import re, sys
from collections import defaultdict

def parse_node(tokens, i):
    if i >= len(tokens): return None
    tok = tokens[i]
    if tok.startswith('<') and tok.endswith('>'):
        return {'uri': tok[1:-1], 'end': i + 1}
    if ':' in tok and not tok.startswith('"') and not tok.startswith('['):
        parts = tok.split(':', 1)
        if len(parts) == 2 and parts[0] and parts[1]:
            return {'uri': tok, 'end': i + 1}
    if tok.startswith('"'):
        val = tok[1:-1]
        datatype = None; lang = None
        dt = re.search(r'\^\^<([^>]+)>$', val)
        if dt: datatype = dt.group(1); val = val[:dt.start()]
        else:
            lm = re.search(r'@[a-zA-Z-]+$', val)
            if lm: lang = lm.group(0)[1:]; val = val[:lm.start()]
        return {'val': val, 'datatype': datatype, 'lang': lang, 'end': i + 1}
    if tok.startswith('['): return {'uri': '_:bnode', 'end': i + 1}
    return None

def expand_uri(uri, prefixes):
    if uri.startswith('<') and uri.endswith('>'): return uri[1:-1]
    if ':' in uri:
        parts = uri.split(':', 1)
        if parts[0] in prefixes: return prefixes[parts[0]] + parts[1]
    return uri

def parse_turtle(filepath):
    triples = []; prefixes = {}
    with open(filepath) as f: content = f.read()
    for m in re.finditer(r'@prefix\s+(\w+):\s*<([^>]+)>\s*\.', content):
        prefixes[m.group(1)] = m.group(2)
    content = re.sub(r'#[^\n]*', '', content)
    pat = r'<[^>]+>|"[^"]*"|\[.*?\]|\w+:\w+|[.,;:<>[\]]|\w+'
    tokens = re.findall(pat, content)
    i = 0
    while i < len(tokens):
        n2 = parse_node(tokens, i)
        if n2 is None: i += 1; continue
        i = n2['end']; subj = n2['uri']
        while i < len(tokens):
            if tokens[i] == '.': i += 1; break
            if tokens[i] == ',': i += 1; continue
            pr = parse_node(tokens, i)
            if pr is None: i += 1; continue
            i = pr['end']; pred_raw = pr['uri']
            if i >= len(tokens): break
            if tokens[i] == '.': i += 1; break
            while True:
                or2 = parse_node(tokens, i)
                if or2 is None: break
                i = or2['end']
                subj_exp = expand_uri(subj, prefixes)
                pred_exp = expand_uri(pred_raw, prefixes)
                if 'val' in or2:
                    triples.append((subj_exp, pred_exp, or2['val'], or2.get('datatype'), or2.get('lang')))
                elif 'uri' in or2:
                    obj_exp = expand_uri(or2['uri'], prefixes)
                    triples.append((subj_exp, pred_exp, obj_exp, None, None))
                if i < len(tokens) and tokens[i] == ',': i += 1; continue
                break
    return triples, prefixes

def is_var(tok): return tok.startswith('?')

def resolve(tok, b, prefixes):
    if is_var(tok): return b.get(tok)
    if tok.startswith('<') and tok.endswith('>'): return tok[1:-1]
    if ':' in tok:
        parts = tok.split(':', 1)
        if parts[0] in prefixes: return prefixes[parts[0]] + parts[1]
    return tok

def eval_filter(expr, b, prefixes):
    expr = expr.strip()
    m = re.match(r'!BOUND\((\?\w+)\)', expr)
    if m: return m.group(1) not in b or b[m.group(1)] == ''
    m = re.match(r'BOUND\((\?\w+)\)', expr)
    if m: return m.group(1) in b and b[m.group(1)] != ''
    m = re.match(r'STRSTARTS\(LCASE\((\?\w+)\),\s*"([^"]*)"\)', expr)
